    [14] = {s = {["|1"] = "Speak to Ohbiru-Dohbiru in the southern Rhinostery building at (J-9).", ["|2"] = "Head to the northern Rhinostery building and speak to Kerutoto.", ["|3"] = "Speak to Ohbiru-Dohbiru & Kenapa-Keppa again to get their food orders.", ["|4"] = "Trade Kerutoto a Grilled Hare.", ["|5"] = "Trade Kenapa-Keppa a Hard-boiled Egg.", ["|6"] = "Trade Ohbiru-Dohbiru a Pamtam Kelp, Tortilla, and Windurstian Tea.", ["|7"] = "(!UPDATE!) No need to speak with Kerutoto."}},
    [15] = {s = {["|1"] = "Speak to Kenapa-Keppa after 7:00 Vana'diel time.", ["|2"] = "Head to Mhaura and speak to Kotan-Purutan at (I-9) - near the ferry ticket area - after 18:00 Vana'diel time to obtain a Small bag.", ["|3"] = "Return to Kenapa-Keppa before 6:00 to complete the quest."}},
    [16] = {s = {["|1"] = "Speak to Ohbiru-Dohbiru to receive a Rhinostery Canteen.", ["|2"] = "Trade the Rhinostery Canteen to the Giddeus Spring at (K-12) or (E-12) in Giddeus to receive a Canteen of Giddeus water.", ["|3"] = "Return to Ohbiru-Dohbiru and trade him the Canteen for your reward."}},
    [17] = {s = {["|1"] = "Give the Purple Ribbon to Kerutoto (J-8) Windurst Waters South (northern Rhinostery building).", ["|2"] = "Go to The Eldieme Necropolis from the (J-10) entrance in Batallia Downs.", ["|3"] = "Upon entering, go straight until you come to an intersection at (J-8) and take a left.", ["|4"] = "Follow the path west until you reach Titan's Gate at (G-8).", ["|5"] = "Go north through Titan's Gate and step on the square of bones, you will fall below and reach Map 2 (L-10).", ["|6"] = "After the fall, go east to the Hume Bones at (M-10).", ["|7"] = "Trade the Purple Ribbon to Hume Bones at (M-10), which will spawn Lich C Magnus.", ["|8"] = "Check the Hume Bones again after NM is defeated to receive Blue Ribbon."}},
    [18] = {s = {["|1"] = "You will have to zone after completing the previous quest.", ["|2"] = "Speak to Kopuro-Popuro to begin this quest.", ["|3"] = "Trade Kopuro-Popuro a Beetle Shell and a Hecteyes Eye to complete the quest."}},
    [19] = {s = {["|1"] = "Speak to Ambrosius to begin this quest.", ["|2"] = "Trade Ambrosius one or all of the following:", ["|3"] = "The more letters you turn in, the higher your reward will be."}},
    [20] = {s = {["|1"] = "Talk to Tosuka-Porika to begin the quest.", ["|2"] = "You will have to go to Giddeus and talk to Quu Bokye, then trade a Silver Beastcoin.", ["|3"] = "Speak to Furakku-Norakku with the key item to complete the quest."}},
    [23] = {s = {["|1"] = "Talk to Paytah who is at the pier near the shopping piers (I-7).", ["|2"] = "Fish the Ripped Cap out of the water and trade it to Paytah.", ["|3"] = "Go to Baren-Moren in Windurst Waters South (H-7) and trade the Ripped Cap to him.", ["|4"] = "Baren-Moren requires 4 Dhalmel Hides to fix the cap.", ["|5"] = "Return the repaired cap to Paytah for your reward."}},
    [24] = {s = {["|1"] = "Speak to Kopuro-Popuro to begin this quest.", ["|2"] = "Trade Kopuro-Popuro a Two-Leaf Mandragora Bud, Insect Wing, and a Rabbit Hide to complete the quest."}},
    [25] = {s = {["|1"] = "Speak to Nanaa Mihgo multiple times till the Quest is flagged.", ["|2"] = "You will have to obtain 4 Yagudo Necklaces.", ["|3"] = "Trade Nanaa Mihgo the Necklaces to complete the Quest."}},
    [26] = {s = {["|1"] = "Speak to Nanaa Mihgo to receive a Sharp gray stone.", ["|2"] = "Speak to Ardea, Bastok Markets (H-8)HP#4 and sell the Stone to her for 10 Gil.", ["|3"] = "Return to Nanaa Mihgo.", ["|4"] = "Speak to Varun, Windurst Woods (H-9).", ["|5"] = "Obtain some Pickaxes, then head to the third floor of Palborough Mines.", ["|6"] = "At (I-9) you will find two Mythril Seams.", ["|7"] = "Trade the Sharp Stone to Varun to complete the quest."}},
    [27] = {s = {["|1"] = "Speak to Kuoh Rhel inside the corral at the Chocobo Stables to begin the quest.", ["|2"] = "Speak to Tapoh Lihzeh at (I-8) past the Dhalmel farm at the medicine shop.", ["|3"] = "Speak to Kuoh Rhel again to complete the quest."}},
    [28] = {s = {["|1"] = "Speak to Moreno-Toeno in the east Aurastery (North Map) to begin the quest.", ["|2"] = "A Bird Feather can be purchased from the Auction House, but the Two-Leaf Mandragora Bud is exclusive and must be obtained from defeating"}},
    [29] = {s = {["|1"] = "Speak to Mashuu-Ajuu who will give you a bag of Herb Seeds and ask you to plant them.", ["|2"] = "You can plant the seeds and grow them into a Deathball or Sobbing Fungus, or you can just purchase them off the Auction House.", ["|3"] = "Trading Mashuu-Ajuu a Deathball will reward you with a Stationery Set and 700 gil.", ["|4"] = "Trading Mashuu-Ajuu a Sobbing Fungus will reward you with a Stationery Set and 500 gil.", ["|5"] = "Repeat attempts will not reward the Stationery Set.", ["|6"] = "You will not get any more Herb Seeds other than the first time.", ["|7"] = "If you set your home point to Windurst and have the appropriate Rhapsodies Key Item, this will only cost 160 by using a BLM Warp."}},
    [30] = {s = {["|1"] = "Speak to Hariga-Origa in Windurst Waters (north) at (F-8).", ["|2"] = "You will be given the Note from Hariga-Origa, and asked to deliver it to Ipupu.", ["|3"] = "She will accept the item and in return give you the Note from Ipupu to deliver to Hariga-Origa.", ["|4"] = "After delivering the note, you will complete the quest and receive your rewards."}},
    [31] = {s = {["|1"] = "Speak to Perih Vashai in Windurst Woods at (K-7).", ["|2"] = "Travel to Sauromugue Champaign and find the cave at (L-10).", ["|3"] = "Once the Old Sabertooth dies naturally, examine the Tiger Bones to get the Old tiger's fang.", ["|4"] = "Return to Perih Vashai to complete the quest."}},
    [32] = {s = {["|1"] = "Speak to Shantotto (K-7) Windurst Walls to begin the Quest.", ["|2"] = "You will have to obtain 2 Bone Chips and 1 Bomb Ash.", ["|3"] = "Trade her the items to complete the Quest."}},
    [33] = {s = {["|1"] = "This Quest can be completed with Making Headlines active, however Hiwon-Biwon's Scoop is taken before this Quest is started.", ["|2"] = "The Quest will not show up in your log until after you have spoken to both Hiwon-Biwon and Shantotto, zoned out, and then returned to speak", ["|3"] = "Speak to Hiwon-Biwon (K-8).", ["|4"] = "Speak to Shantotto (K-8).", ["|5"] = "Zone out of the area and then back and speak to Shantotto (K-8).", ["|6"] = "For her first question, choose either answer.", ["|7"] = "Shantotto asks you to bring her 2 Bomb Arms, 1 Revival Tree Root, and 1 Hiwon's Hair.", ["|8"] = "Trade the items to Shantotto to complete the Quest."}},
    [34] = {s = {["|1"] = "Speak to Yoran-Oran, who will request an item."}},
    [35] = {s = {["|1"] = "If Zayhi-Bauhi speaks normally rather than coughing, try speaking to Kalupa-Tawalupa and Rutango-Botango in front of him to receive the", ["|2"] = "Speak to Raamimi to receive Honey.", ["|3"] = "Trade Honey to Zayhi-Bauhi, then speak to Kalupa-Tawalupa and Rutango-Botango.", ["|4"] = "Trade 4 more Honey, one at a time, to Zayhi-Bauhi."}},
    [36] = {s = {["|1"] = "Talk to Kohlo-Lakolo behind warehouse #1 at G-5 in Port Windurst for a cut-scene.", ["|2"] = "Obtain and trade him a Rarab Tail for a cut-scene and your reward to complete the quest."}},
    [37] = {s = {["|1"] = "Speak to Naiko-Paneiko in Southern Windurst Waters (C-11) at The Tarutaru Times Company to begin the quest.", ["|2"] = "Speak to the following NPCs to retrieve key items:", ["|3"] = "Return to Naiko-Paneiko, he will request that you check out a lead in the Inner Horutoto Ruins.", ["|4"] = "Enter from East Sarutabaruta (J-7) to enter the first map of Inner Horutoto Ruins.", ["|5"] = "Examine the Cracked Wall at (G-8) to enter the second map.", ["|6"] = "Examine the Mahogany Door at (G-8) to get a message to confirm the Windurst Woods scoop.", ["|7"] = "Return to Naiko-Paneiko to finish the quest and receive your reward."}},
    [38] = {s = {["|1"] = "You must zone after completing Making Headlines before starting this quest.", ["|2"] = "Speak to Naiko-Paneiko to begin the quest.", ["|3"] = "Head to the Ferry - Mhaura/Selbina and begin to fish for Ocean Crabs.", ["|4"] = "The crabs will drop the Bronze Box you need to complete this quest.", ["|5"] = "Trade the Bronze Box to Naiko-Paneiko to complete this quest."}},
    [39] = {s = {["|1"] = "Speak to Illu Bohjaa to begin this quest.", ["|2"] = "Trade Illu Bohjaa either 3x Silk Threads or 3x Crawler Calculus."}},
    [40] = {s = {["|1"] = "Before you begin, you are required to zone if you just completed Truth, Justice, and the Onion Way!.", ["|2"] = "Speak to Kohlo-Lakolo Port Windurst behind the warehouse at (G-5).", ["|3"] = "Retrieve 4 Wild Onions and trade them to him.", ["|4"] = "Head to House of the Hero in Windurst Walls (G-3) and try to enter to see a cut-scene.", ["|5"] = "Return to Kohlo-Lakolo and speak with him to complete the quest and receive your reward."}},
    [41] = {s = {["|1"] = "Zone after finishing the previous quest.", ["|2"] = "Speak to Kohlo-Lakolo for a cut-scene, then to Pichichi near him, who directs you to her mother.", ["|3"] = "Go to Windurst Waters and speak to Chamama at (F-10) (use Home Point #4), who requests four balls of Saruta Cotton to make a Fake moustache.", ["|4"] = "Give Chamama the four Saruta Cotton, then return to Kohlo-Lakolo for a cut-scene."}},
    [42] = {s = {["|1"] = "Zone after completing the previous quest.", ["|2"] = "Speak to Kohlo-Lakolo for a storytelling sequence to begin this quest.", ["|3"] = "Head to Castle Oztroja and head to the door at (I-8) on the first map.", ["|4"] = "Using the handles in front of the door, intentionally activate the trap door and fall down it.", ["|5"] = "Check the Blank Target in this room to receive an Old ring.", ["|6"] = "Return to Kohlo-Lakolo who will send you to the \"House of the Hero\" Windurst Walls (G-3) for your reward.", ["|7"] = "Zone and return to Kohlo-Lakolo to receive your reward."}},
    [43] = {s = {["|1"] = "You will have to zone after completing the previous quest.", ["|2"] = "Talk to Kororo in the Manustery at (H-9) in Windurst Woods.", ["|3"] = "Talk to the Cardian that Kororo mentions.", ["|4"] = "Leave Windurst Woods, then return after one earth minute and talk to Kororo again.", ["|5"] = "The Cardian you are looking for is the Five of Spades.", ["|6"] = "Go to Buburimu Peninsula and speak to Five of Spades.", ["|7"] = "Return to Kororo to receive your reward.", ["|8"] = "This quest cannot be flagged if you have Windurst Mission 9-2 open.", ["|9"] = "This quest cannot be flagged if you have the quest The Kind Cardian open."}},
    [44] = {s = {["|1"] = "You will have to zone after completing the previous quest.", ["|2"] = "Speak to Kopuro-Popuro to begin this quest.", ["|3"] = "Trade Kopuro-Popuro a Luminicloth, Revival Tree Root, and a Wolf Hide for your reward."}},
    [45] = {s = {["|1"] = "Speak to Kuoh Rhel.", ["|2"] = "Speak to Matata (K-12).", ["|3"] = "Speak to Ranpi-Monpi in the northern part of Windurst Waters (D-9).", ["|4"] = "Speak to Kuoh Rhel to complete the quest.", ["|5"] = "(Optional) Speak to Matata again for some lore about how the chocobo got sick."}},
    [46] = {s = {["|1"] = "Speak to Mashuu-Ajuu (K-6) and then Paku-Nakku to begin this quest.", ["|2"] = "Next, speak to Maabu-Sonbu, Port Windurst (E-7) (Home Point #1).", ["|3"] = "Grab some Sickles and head to Pashhow Marshlands (via Derfland).", ["|4"] = "Harvest at the ??? at (E-5) to obtain the Blazing Peppers.", ["|5"] = "Trade the peppers to Paku-Nakku.", ["|6"] = "Talk to Pechiru-Mashiru.", ["|7"] = "Talk to Paku-Nakku again.", ["|8"] = "Finally, speak to Pechiru-Mashiru for your reward.", ["|9"] = "After trading the remedy it will lock you out of being able to trade the Blazing Pepper."}},
    [47] = {s = {["|1"] = "Speak to Apururu to begin this quest.", ["|2"] = "Kill Cursed Weapons in Xarcabard until you get a Bruised Starfruit.", ["|3"] = "Trade the Bruised Starfruit to Apururu for your reward.", ["|4"] = "Trading a Bruised Starfruit to Apururu after completing this quest will reward you with 1,000 gil."}},
    [48] = {s = {["|1"] = "Speak to Hakkuru-Rinkuru (Port Windurst, E-7 Orastery) to begin the quest.", ["|2"] = "Speak to the War Warlock Captains here in the Orastery.", ["|3"] = "Obtain a Rose Wand, Oak Staff, and Mythril Rod.", ["|4"] = "Trade the Rose Wand, Oak Staff, and Mythril Rod to Hakkuru-Rinkuru for the cutscene that completes the quest."}},
    [50] = {s = {["|1"] = "Speak to Moari-Kaaori in Windurst Waters to begin this quest (HP #3 is the closest).", ["|2"] = "Speak to Ohbiru-Dohbiru (J-9, southern Rhinostery building) who will ask you questions about the flower you are looking for.", ["|3"] = "Head to Tahrongi Canyon (F-6) and examine the Tahrongi Cacti there to get a Tahrongi Cactus.", ["|4"] = "Give the flower to Moari-Kaaori for your reward."}},
    [51] = {s = {["|1"] = "Obtain a Royal Jelly.", ["|2"] = "Trade the Royal Jelly to Maysoon for your reward."}},
    [52] = {s = {["|1"] = "Speak to Tokaka to begin this quest.", ["|2"] = "Trade Tokaka a Bastore Sardine to complete this quest."}},
    [53] = {s = {["|1"] = "To start this quest, speak to Sigismund on top of the Orastery at (E-7) of Port Windurst.", ["|2"] = "Speak with Tohopka, who is standing right next to Sigismund, at (E-7).", ["|3"] = "You can also find the Starfall Tear on the AH under the \"Other\" category.", ["|4"] = "With some Scales in your possession, head out to West Sarutabaruta.", ["|6"] = "Head back to Sigismund and give him the Tears."}},
    [60] = {s = {["|1"] = "Speak to Tapoh Lihzeh.", ["|2"] = "Trade her either 3 Beehive Chips or 2 Remi Shells to complete the quest.", ["|3"] = "Your reward depends on which items you gave her to complete the quest."}},
    [61] = {s = {["|1"] = "Speak to Soni-Muni in Windurst Woods (H-10) to begin the quest.", ["|2"] = "Obtain a Scorpion Stinger:", ["|3"] = "Trade the Scorpion Stinger to Soni-Muni for your reward."}},
    [62] = {s = {["|1"] = "Speak with Gioh Ajihri in Windurst Woods at (K-5) to begin the quest.", ["|2"] = "Bring the Twinstone Earring back to Gioh for your reward."}},
    [63] = {s = {["|1"] = "Speak to Shantotto (K-7) who will ask you a few questions.", ["|2"] = "Head to the tower at (I-7) in Beaucedine Glacier, speak to Torino-Samarino, speak to him again and choose the first option to receive", ["|3"] = "Head to Fei'Yin.", ["|4"] = "Return to Shantotto to complete the Quest and to receive your reward.", ["|5"] = "The completion of this Quest is one of the requirements to obtain Shantotto's Trust."}},
    [64] = {s = {["|1"] = "Speak to Gantineux on the second floor of the Rarab Hostelry (E-10).", ["|2"] = "Gantineux will give you the Spirit incense, and ask you to travel to Eldieme Necropolis.", ["|3"] = "Head to Eldieme Necropolis and look for a ??? that spawns in one of four locations.", ["|4"] = "Click the ???.", ["|5"] = "Go back to Gantineux.", ["|6"] = "Go to Northern San d'Oria and talk to Eperdur (M-7) upstairs in the Cathedral to complete the quest."}},
    [65] = {s = {["|1"] = "(optional) Talk to Ojha Rhawash.", ["|2"] = "She won't come out and say it at first, but she would like a Lilac.", ["|3"] = "Trade it to her to complete the quest."}},
    [66] = {s = {["|1"] = "Begin the quest by speaking with Chumimi, found in the basement of Heavens Tower (Windurst).", ["|6"] = "Take the Glowstone that drops from the NM and return to Chumimi."}},
    [67] = {s = {["|1"] = "Zoning out of the tower is required after finishing the previous quest.", ["|2"] = "Begin quest by speaking with Chumimi, found in the basement of Heavens Tower (Windurst).", ["|3"] = "After speaking with Chumimi, head to the basement of Crawlers' Nest and obtain a Bag of Seeds drop from either a Fire Elemental or Water", ["|4"] = "Return to Chumimi and trade her the Bag of Seeds.", ["|5"] = "Following this cutscene, head to Castle Zvahl Baileys and defeat Demon Generals, Magistrates, Chancellors or Commanders for a Whine Cellar", ["|6"] = "Zone into Castle Zvahl Keep", ["|7"] = "Head to the Ore Door at (H-7) then trade the Whine Cellar Key to the Ore Door for a cutscene and the \"Foe Finder Mk.", ["|8"] = "Return to Chumimi after the cutscene in the Keep, and following another short sequence, the quest is completed and you'll obtain BLM AF1"}},
    [68] = {s = {["|1"] = "Begin quest by speaking with Chumimi as Black Mage in the basement of Heavens Tower.", ["|10"] = "Click the ??? again for another cutscene", ["|11"] = "Return to Chumimi for the final cutscene and your reward.", ["|2"] = "After the cutscene, trade a Silk Cloth to Koru-Moru (E-7) in Windurst Walls.", ["|3"] = "Return to Chumimi afterwards to receive the \"Sluice Surveyor Mk.", ["|4"] = "Proceed to Toraimarai Canal and locate two ??? points.", ["|5"] = "The first ??? is in the North-east corner of (H-7) on map 1.", ["|6"] = "The second ??? is at (I-9) on (map 1).", ["|7"] = "At one of the ??? you'll get a cutscene then be asked for \"the Mage's black power\"."}},
    [69] = {s = {["|1"] = "Talk to Nanaa Mihgo as a Thief to begin this quest, and she will give you a Letter from the Tenshodo.", ["|2"] = "Head to Lower Jeuno and talk to Harnek inside of the Tenshodo at (J-7) for a cutscene.", ["|3"] = "You will be given the Tenshodo envelope.", ["|4"] = "Travel to Selbina and talk to Elfriede (J-9) of the Shepherd's Muster Inn.", ["|5"] = "Quadav Stew can only be stolen from certain Quadavs in Beadeaux.", ["|6"] = "Head to Beadeaux and Steal from Garnet Quadav, Silver Quadav, Zircon Quadav, and/or Bronze Quadav until you obtain the Quadav Stew.", ["|7"] = "Once you get the Quadav Stew, go back to Selbina and trade the stew to Elfriede (J-9).", ["|8"] = "You will receive the Signed envelope.", ["|9"] = "Head back to Lower Jeuno and talk to Harnek (J-7) for a final cutscene and to receive your reward."}},
    [70] = {s = {["|1"] = "Speak to Nanaa Mihgo in Windurst Woods (J-3) to begin.", ["|15"] = "You'll find a ??? click on it and spawn Gambilox Wanderling.", ["|17"] = "Head back to Lower Jeuno and trade your Regal Die to Sniggnix to get the Second signed forged envelope.", ["|18"] = "Head back to Windurst Woods and speak to Nanaa Mihgo again to get your Rogue's Bonnet!", ["|2"] = "Optional: Speak to Cha Lebagta and Bopa Greso who are just south of Nanaa Mihgo at J-4 for a couple clues.", ["|3"] = "Head to Sauromugue Champaign and check the ???s in the following locations to attempt to spawn Climbpix Highrise.", ["|4"] = "There are 6 towers in all that are represented by dark dots on the Sauromugue Champaign map.", ["|5"] = "Climbpix Highrise drops a Grapnel.", ["|6"] = "Next, go to the tower at I/J-7 and take off all your equipment.", ["|7"] = "Trade your Grapnel to the ??? and watch the cutscene to get your First signed forged envelope.", ["|8"] = "Go to Lower Jeuno (H-10) and talk to Sniggnix (in the back hallway at Muckvix's Junk Shop).", ["|9"] = "Keep rolling against him until you beat him."}},
    [71] = {s = {["|1"] = "Speak to Nanaa Mihgo in Windurst Woods (J-3) to receive the Cat Burglar's note.", ["|10"] = "Head to Windurst Woods and talk to Nanaa Mihgo.", ["|11"] = "You'll need a Pickaxe for this next step.", ["|12"] = "Go to Ordelle's Caves.", ["|13"] = "NOTE: If you have the Proto-Waypoint in La Theine Plateau, you can warp to the valley and skip the below Ordelle's Caves.", ["|14"] = "Head to the middle of the valley and find the ??? at the southwest corner of (H-10).", ["|2"] = "Go to Lower Jeuno (G-10) and speak to Yatniel on the top floor.", ["|3"] = "Trade the Quake Grenades to him for a clue.", ["|4"] = "Go to Mhaura (H-8) and speak to Hagain who is located in one of the upstairs rooms in the Sailor's Stay.", ["|5"] = "Head to Garlaige Citadel via the main entrance.", ["|6"] = "You will now need to examine multiple ??? in a specific order.", ["|7"] = "The last ??? will spawn a Bomb named Chandelier.", ["|8"] = "Using Hide or Spectral Jig immediately after the cutscene is the recommended way to avoid detection long enough to claim.", ["|9"] = "Go back to Mhaura and trade the Chandelier Coal to Hagain."}},
    [72] = {s = {["|1"] = "Talk to Perih Vashai in Windurst Woods (K-7) and recieve temporary key item Chieftainness's twinstone earring.", ["|2"] = "She will send you to Ranguemont Pass to look for Semih Lafihna.", ["|3"] = "After arriving, you will not find Semih Lafihna there.", ["|4"] = "Perchond will tell you about Semih Lafihna coming to him and questioning him about a creature he encountered in Ranguemont Pass.", ["|5"] = "Go to the pond at (E-5) and kill Evil Weapons until you get the drop Glittersand.", ["|6"] = "Trade the Pinch of Glittersand to Perchond, he will give you another temporary key item, Perchond's envelope and explain there is a", ["|7"] = "Head to Jugner Forest at the very top of (I-6) near the lake and speak with Alexius.", ["|8"] = "Go to (H-6) in Jugner Forest and find the ??? on a tree.", ["|9"] = "After the cutscene, return to Perih Vashai and receive the Sniping Bow."}},
    [73] = {s = {["|1"] = "Talk to Perih Vashai in Windurst Woods (K-7) and she will tell you to go to Mhaura and visit the Blacksmiths' guild.", ["|2"] = "In Mhaura head to (F-9) to speak with Koh Lenbalalako.", ["|3"] = "Enter Eldieme Necropolis through Batallia Downs at (I-10) and get another cutscene with the Mithran Tracker telling you to examine the", ["|4"] = "Head to (G-9) and examine the Gravestone to trigger another cutscene with the Mithra Tracker.", ["|5"] = "After the cutscene head back to Windurst Woods and speak with Perih Vashai again.", ["|6"] = "You will get another cutscene with the Mithran Tracker, where you are told by Perih Vashai to head to Castle Oztroja to search a pool for", ["|7"] = "The next step in Castle Oztroja requires Scavenge, so set your job or subjob accordingly.", ["|8"] = "Take the Old Earring and trade it to Perih Vashai for a cutscene and the Hunter's Beret."}},
    [74] = {s = {["|1"] = "Talk to Perih Vashai in Windurst Woods (K-7) for a cutscene where she will tell you to go to Mhaura.", ["|2"] = "In Mhaura speak twice with Koh Lenbalalako (F-9) for a cutscene.", ["|3"] = "Zone into Xarcabard for a cutscene hinting to look near Castle Zvahl Baileys.", ["|4"] = "Find the cave at (E-7) in Xarcabard and examine the ??? where you will get another cutscene and then a Koenigstiger will pop.", ["|5"] = "Now head south to the cave at (E-8) and check the ??? here for another cutscene.", ["|6"] = "After the cutscene is over, check the ??? again for 99 Ice Arrows.", ["|7"] = "Head back to Windurst Woods and talk once more to Perih Vashai for the final cutscene and your reward."}},
    [75] = {s = {["|2"] = "Go to Windurst Walls (G-3) and examine the door of the House of the Hero for a cutscene.", ["|3"] = "You will be instructed to experience 7 types of weather in outdoor areas.", ["|8"] = "Once you've experienced all 7 weather effects, you'll receive a cutscene with Carbuncle who requests you go to La Theine Plateau.", ["|9"] = "Go to La Theine Plateau (G-6) and trade the Carbuncle's Ruby to the ??? for a cutscene, and to complete the quest."}},
    [76] = {s = {["|1"] = "You'll need to zone again if you haven't done so yet after receiving Bouncer Club.", ["|2"] = "Talk to Kohlo-Lakolo for a cut scene to start the quest.", ["|3"] = "Head to Windurst Waters(South) (a short walk away, or use Home Point #3) and speak to Honoi-Gomoi - (E-7) for a cut scene.", ["|4"] = "Get a Star Spinel from Spelunking Sabotender in Quicksand Caves.", ["|5"] = "Bring the Star Spinel to Honoi-Gomoi, who will reward you with the Star Necklace after a cut scene.", ["|6"] = "Talk to Kohlo-Lakolo for a cut scene, and then once again back to Honoi-Gomoi for a cut scene to complete the quest."}},
    [77] = {s = {["|1"] = "Zone after finishing the previous quest.", ["|2"] = "Speak to Honoi-Gomoi to begin the quest.", ["|3"] = "Speak to Kohlo-Lakolo, Port Windurst (G-5).", ["|4"] = "Head to Windurst Walls (G-3) and check the door at the House of the Hero.", ["|5"] = "Head to Toraimarai Canal and open a Coffer there to obtain the Joker card.", ["|6"] = "If you spoke to Joker during the previous cut-scene, return to to the House of the Hero for your reward.", ["|7"] = "If you spoke to Apururu, return to the Manustery in Windurst Woods (use Home Point #3).", ["|8"] = "Return to Honoi-Gomoi to complete the quest."}},
    [78] = {s = {["|1"] = "Speak to Kohlo-Lakolo to begin this quest.", ["|2"] = "Speak to Chamama, Windurst Waters (F-10).", ["|3"] = "She will make you the Invisible man sticker you need if you first bring her Shoalweed.", ["|4"] = "Return to Kohlo-Lakolo for your reward.", ["|5"] = "If you have killed Fenrir after obtaining Windurst Rank 10, you will have the Dark Mana Orb in your Temporary Key Items.", ["|6"] = "Zoning and talking to Kohlo-Lakolo again with this key item will give a final, concluding cutscene."}},
    [79] = {s = {["|5"] = "After answering the questions, head to the western Acolyte Hostel building at (K-5) for a cutscene.", ["|6"] = "You will receive the Thesis on alchemy.", ["|9"] = "Return to Koru-Moru in a few day-aroos (after JP midnight) for your reward."}},
    [80] = {s = {["|1"] = "Speak to Ohbiru-Dohbiru for a cutscene.", ["|2"] = "Trade Ohbiru-Dohbiru 3 Starmite Shells to complete this quest."}},
    [81] = {s = {["|1"] = "While you are on Summoner as a main job, interact with the House of the Hero in Windurst Walls (Home Point #1) to speak to Carbuncle.", ["|2"] = "Speak to Juroro in Port Bastok at (I-8) (Home Point #1).", ["|3"] = "Make your way through the Quicksand Caves to the Cloister of Tremors.", ["|5"] = "Speak to Juroro again.", ["|6"] = "Speak to Koru-Moru in Windurst Walls at (E-7) to complete the quest and receive your reward."}},
    [82] = {s = {["|1"] = "While your main job is Summoner, interact with the House of the Hero in Windurst Walls for a cutscene with Carbuncle.", ["|2"] = "Speak to Koru-Moru in Windurst Walls at (E-7).", ["|3"] = "Trade Koru-Moru x4 Astragalos.", ["|4"] = "He will task you to speak to the following three NPCs in any order:", ["|5"] = "Speak to Gulmama in Northern San d'Oria at (E-7) to receive an Ice Pendulum.", ["|6"] = "Head to the Cloister of Frost in Fei'Yin.", ["|7"] = "Trade the Ice Pendulum to the Protocrystal to enter a battlefield.", ["|8"] = "Defeat them and then speak to Koru-Moru to complete the quest and receive your reward."}},
    [83] = {s = {["|1"] = "Interact with the House of the Hero in Windurst Walls while your job is set to Summoner to begin this quest.", ["|11"] = "Defeat Ogmios, who is a Manticore.", ["|12"] = "Return to Windurst Walls and talk to Koru-Moru to receive your Evoker's Horn and to complete the quest.", ["|2"] = "Speak to Koru-Moru at (E-7).", ["|3"] = "Travel to Mhaura and speak to Ripapa (I-9) to obtain a Lightning Pendulum.", ["|4"] = "The cutscene that follows the next fight is known to cause problems for Windower addons.", ["|5"] = "Trade the Lightning Pendulum to the Lightning Protocrystal inside of the Cloister of Storms for a cutscene and to enter a BC.", ["|6"] = "Defeat both Lightning Gremlin and Thunder Gremlin.", ["|7"] = "Return to Windurst Walls and speak to Koru-Moru to obtain a Daze-breaker charm.", ["|8"] = "Head to Rabao and talk to Agado-Pugado (G-9) to receive a Wind Pendulum.", ["|9"] = "Trade the Wind Pendulum to the Wind Protocrystal inside of the Cloister of Gales for a cutscene and to enter a BC."}},
    [84] = {s = {["|1"] = "Speak to Lumomo in the Timbre Timbers Tavern at (F-10).", ["|2"] = "Travel to the Maze of Shakhrami and speak to Ahko Mhalijikhari (C-9) to receive the level cap status.", ["|3"] = "Travel to (H-8) on map 1 to reach map 2.", ["|4"] = "Travel to (I-10) on map 2 and examine the ??? to spawn three Wyrmflys (Fly NMs).", ["|5"] = "After defeating all three, examine the ??? once more to receive the Indigested meat.", ["|6"] = "Report to Lumomo for your reward."}},
    [85] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "Go back and speak with Perih Vashai to receive your reward.", ["|2"] = "Speaking with Perih Vashai will grant you the key item Weapons Training Guide as well as the Bow of Trials.", ["|6"] = "Trade the Bow of Trials back to Perih Vashai.", ["|7"] = "Take Silent Oil and Prism Powder with you and head to Kuftal Tunnel.", ["|8"] = "Once you are at the Cape, travel to (G-7).", ["|9"] = "This fight is against Stolas, a Bird."}},
    [86] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|10"] = "This fight is against Eldhrimnir, a magic pot.", ["|11"] = "Go back and speak with Kuroido-Moido to receive your reward.", ["|2"] = "Speaking with Kuroido-Moido will grant you the key item Weapons Training Guide as well as the Club of Trials.", ["|6"] = "Trade the Club of Trials back to Kuroido-Moido.", ["|7"] = "Take Silent Oil and head to Ro'Maeve.", ["|8"] = "Inside Ro'Maeve, go down the northeastern stairs and turn immediately east.", ["|9"] = "Through the door, turn right and follow the long hallway southeast to (M-8), past the Moongate."}},
    [87] = {s = {["|1"] = "You cannot start this quest if you have another Weapon Skill Quest active.", ["|12"] = "This fight is against Cailleach Bheur, a skeleton.", ["|13"] = "Go back and speak with Shantotto to receive your reward.", ["|2"] = "Speaking with Shantotto will grant you the key item Weapons Training Guide as well as the Pole of Trials.", ["|6"] = "Trade the Pole of Trials back to Shantotto.", ["|7"] = "Take Ifrit's Cauldron HP #1 to map 7.", ["|8"] = "Alternatively, if you don't have the HP."}},
    [88] = {s = {["|1"] = "You can only have one Escort for Hire quest active at any time.", ["|10"] = "You will have 30 minutes to complete this quest.", ["|11"] = "Escort Wanzo-Unzozo until he stops on his own.", ["|12"] = "Return to Dehn Harzhapan for your reward.", ["|2"] = "Escort for Hire quests can be deactivated by returning to the NPC that began the quest.", ["|3"] = "Only one Escort for Hire quest can be completed each Conquest Tally.", ["|4"] = "Can summon trusts.", ["|5"] = "Zoning in with an Adventuring Fellow despawns the Escort NPC.", ["|6"] = "Speak to Dehn Harzhapan to begin the quest.", ["|7"] = "Head to Garlaige Citadel.", ["|8"] = "As soon as you zone in you will receive a cutscene.", ["|9"] = "Once the cutscene is over, an NPC named Wanzo-Unzozo will spawn."}},
    [90] = {s = {["|1"] = "Speak with Leepe-Hoppe on top of the Rhinostery to start the quest.", ["|2"] = "Leepe-Hoppe requires 3 items, all of which must be farmed from Chains of Promathia areas.", ["|3"] = "You need to trade all 3 of these items to Leepe-Hoppe at once to complete the quest."}},
    [91] = {s = {["|1"] = "Speak to Leepe-Hoppe to initiate the quest.", ["|10"] = "Head to Beaucedine Glacier (I-7) and speak with Torino-Samarino at the tower.", ["|11"] = "Speaking to Leepe-Hoppe after completing the quest will reward you with a Cache-nez.", ["|2"] = "Speak with Jakoh Wahcondalo at (J-9) in Kazham.", ["|3"] = "Speak with Romaa Mihgo at (H-11) in Kazham.", ["|4"] = "Travel to Yuhtunga Jungle (K-7) in search of a ??? overlooking Gemini Falls.", ["|5"] = "Click the ??? again after defeating the Nasus.", ["|6"] = "Return to Kazham and speak with Romaa Mihgo.", ["|7"] = "To progress further, you will need a Mutton Tortilla, Habaneros, and a serving of Black Curry.", ["|8"] = "Head to Norg (K-8) to speak with Comitolus after getting your food items.", ["|9"] = "Trade all three food items to Comitolus to receive the next cutscene."}},
    [92] = {s = {["|1"] = "Speak to Chipmy-Popmy to begin this quest.", ["|10"] = "(Optional) Speak to Chipmy-Popmy again for some closing dialogue.", ["|2"] = "Hop aboard the Manaclipper in Bibiki Bay to Bibiki Bay - Purgonorgo Isle.", ["|3"] = "Head to (H-9) to find a ???.", ["|4"] = "Examine the ??? to spawn 6 Peerifools.", ["|5"] = "Once defeated, check the ??? again to receive the Deed to Purgonorgo Isle.", ["|6"] = "Return to Chipmy-Popmy. (may have to talk to him multiple times, make sure you get a cutscene)", ["|7"] = "Head to Boneyard Gully by going through Attohwa Chasm.", ["|8"] = "As soon as you zone into Boneyard Gully you will get a cutscene and the Map of the Attohwa Chasm (if you do not already own it).", ["|9"] = "Return to Chipmy-Popmy for the 3,200 gil and 2,000 Experience Points."}},
    [93] = {s = {["|1"] = "Speak to Kerutoto, Windurst Waters South (J-8) HP #3, for a cutscene that begins the quest and key item Vial of dream incense.", ["|10"] = "Select the Memento Circle and pick Waking Dreams.", ["|11"] = "Defeat Diabolos Prime to receive a key item: Whisper of dreams.", ["|12"] = "Return to Kerutoto with the whisper and she will provide several reward options including the ability to summon Diabolos.", ["|13"] = "Up to 6 party members can enter the arena.", ["|14"] = "Each party member must have their own Vial of dream incense", ["|15"] = "Time limit is 30 minutes", ["|16"] = "You can only select 1 of the rewards Kerutoto offers at any time", ["|17"] = "You may repeat this quest once per Earth day.", ["|18"] = "When clearing for the first time, the event with Diabolos in The Shrouded Maw will change depending on your progress in Chains of Promathia", ["|2"] = "Head to Pso'Xja Home Point #1.", ["|3"] = "Travel to Beaucedine Glacier (H-8) and enter Pso'Xja.", ["|4"] = "Once inside, the correct displacement sequence is red > purple > red > purple.", ["|5"] = "Take the elevator down.", ["|6"] = "Head forward (North), then left (West) at the intersection.", ["|7"] = "Use the Stone Gate and select Yes when asked to use the Pso'Xja pass.", ["|8"] = "The Home Point is just past the gate on the left.", ["|9"] = "Head down the steps into The Shrouded Maw."}},
    [94] = {s = {["|1"] = "Speak with Ibwam to recieve a Green Sentinel badge and begin the quest.", ["|2"] = "Speak to all twenty (20) NPCs in the below chart.", ["|3"] = "Return to Ibwam."}},
    [95] = {s = {["|1"] = "The quest begins after speaking to Khoto Rokkorah and receiving a cutscene.", ["|5"] = "Return to Khoto Rokkorah to receive the final cutscene and reward."}},
    [96] = {s = {["|1"] = "Speak to Wetata in Windurst Woods at (G-10), she will give you the Green institute card.", ["|2"] = "Head to Heavens Tower and speak to Kupipi."}},
}
